#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_N 1000
#define MAX_M 1000

// DP array for the game value (difference from first player's perspective)
int dp[MAX_N][MAX_M];
int grid[MAX_N][MAX_M];

int max(int a, int b) {
    return a > b ? a : b;
}

int min(int a, int b) {
    return a < b ? a : b;
}

int main() {
    int n, m;
    scanf("%d %d", &n, &m);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            scanf("%d", &grid[i][j]);
        }
    }

    // First player wants to maximize the difference, second player wants to minimize it.
    // We fill DP from bottom-right to top-left.
    // The value dp[i][j] represents the optimal value of the subgame starting from (i,j)
    // assuming it's the first player's turn when total moves parity is even.
    // Since the path length from (i,j) to (n-1,m-1) is fixed,
    // we know whose turn it is based on (i+j) parity.

    for (int i = n - 1; i >= 0; i--) {
        for (int j = m - 1; j >= 0; j--) {
            if (i == n - 1 && j == m - 1) {
                // At the southeast corner, the game ends.
                // The territory split happens based on the path.
                // Actually the final cell belongs to the boundary.
                // The difference contributed by cells is determined later.
                // For the DP we need a base value representing the final state.
                // Since no more moves, the value contributed by future cells is 0.
                dp[i][j] = 0;
                continue;
            }

            int moves_left = (n - 1 - i) + (m - 1 - j);
            // If moves_left is odd, it's second player's turn (minimizer)
            // If even, it's first player's turn (maximizer)

            if ((moves_left % 2) == 0) {
                // First player's turn (maximizer)
                int best = -1000000000;
                if (i + 1 < n) {
                    best = max(best, dp[i+1][j] + grid[i+1][j]);
                }
                if (j + 1 < m) {
                    best = max(best, dp[i][j+1] + grid[i][j+1]);
                }
                dp[i][j] = best;
            } else {
                // Second player's turn (minimizer)
                int worst = 1000000000;
                if (i + 1 < n) {
                    worst = min(worst, dp[i+1][j] - grid[i+1][j]);
                }
                if (j + 1 < m) {
                    worst = min(worst, dp[i][j+1] - grid[i][j+1]);
                }
                dp[i][j] = worst;
            }
        }
    }

    // The game starts at (0,0) and the first move is made by the first player.
    // The value dp[0][0] represents the optimal difference from that point onward,
    // but we haven't accounted for the starting cell (0,0).
    // The starting cell is part of the boundary.
    // According to the problem, the boundary divides the island.
    // Cells on the path (including start and end) are on the boundary.
    // The territory scores are computed from cells strictly in each territory.
    // The absolute difference is what we want.

    // The DP as computed gives the value of the game where each move adds the cell
    // entered to the moving player's territory? Let's re-evaluate.

    // Actually, the typical solution: 
    // The first player's territory is northeast of the path, second player's is southwest.
    // The path cells themselves are not counted.
    // This is equivalent to: each time we move east, the cell above (north) goes to first player,
    // and each time we move south, the cell to the left (west) goes to second player.
    // But we need to be careful with boundaries.

    // Let's think differently: we can compute the total sum of all cells.
    // Then the difference = (sum of first player's territory) - (sum of second player's territory).
    // Since total = first + second + boundary, we have diff = 2*first + boundary - total.
    // But we want absolute value.

    // A simpler approach: simulate the game with minimax where the value is the difference
    // (first - second) from the perspective of the first player.
    // When first player moves east from (i,j) to (i,j+1), all cells above the new segment
    // (i.e., cells (r, j) for r < i) go to first player? No, that's not right.

    // The standard known solution: 
    // The game is equivalent to: players take turns picking rows or columns.
    // Actually, the path from (0,0) to (n-1,m-1) moving only south/east.
    // The northeast territory consists of cells that are above and to the right of the path.
    // The southwest territory consists of cells below and to the left.
    // This can be computed by: when moving east, the entire column to the north of the current row
    // becomes first player's territory. When moving south, the entire row to the west becomes second player's.
    // So the game is: we have an array of row values and column values.

    // Let's precompute row sums and column sums.
    int row_sum[MAX_N];
    int col_sum[MAX_M];
    memset(row_sum, 0, sizeof(row_sum));
    memset(col_sum, 0, sizeof(col_sum));

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            row_sum[i] += grid[i][j];
            col_sum[j] += grid[i][j];
        }
    }

    // Now the game: starting from (0,0).
    // If we move east from (i,j), we add col_sum[j] (the column we leave behind to the north)
    // to first player's score (since all cells above the path in that column go to first player).
    // If we move south from (i,j), we add row_sum[i] to second player's score (cells to the left).
    // But careful: the starting cell (0,0) is on the boundary, and the final cell (n-1,m-1) as well.
    // The territory cells are those strictly northeast or southwest.

    // Let's define the game value as (first - second).
    // When first player moves east: first gains col_sum[j] (the column j above row i).
    // When first player moves south: second gains row_sum[i] (the row i left of column j),
    // so first loses that amount -> subtract row_sum[i].
    // Similarly for second player's moves, they will try to minimize first's advantage.

    // So we can set up DP where dp[i][j] is the optimal difference from (i,j) to end,
    // assuming it's first player's turn when (i+j) is even.

    // Reinitialize dp
    for (int i = n - 1; i >= 0; i--) {
        for (int j = m - 1; j >= 0; j--) {
            if (i == n - 1 && j == m - 1) {
                dp[i][j] = 0;
                continue;
            }

            int moves_left = (n - 1 - i) + (m - 1 - j);
            if ((moves_left % 2) == 0) {
                // First player's turn
                int best = -1000000000;
                if (i + 1 < n) {
                    // move south: second gets row_sum[i], so first loses that
                    best = max(best, dp[i+1][j] - row_sum[i]);
                }
                if (j + 1 < m) {
                    // move east: first gets col_sum[j]
                    best = max(best, dp[i][j+1] + col_sum[j]);
                }
                dp[i][j] = best;
            } else {
                // Second player's turn
                int worst = 1000000000;
                if (i + 1 < n) {
                    // second moves south: second gets row_sum[i], so first loses
                    worst = min(worst, dp[i+1][j] - row_sum[i]);
                }
                if (j + 1 < m) {
                    // second moves east: first gets col_sum[j]
                    worst = min(worst, dp[i][j+1] + col_sum[j]);
                }
                dp[i][j] = worst;
            }
        }
    }

    int diff = dp[0][0];
    if (diff < 0) diff = -diff;
    printf("%d\n", diff);

    return 0;
}

