    int h, w;
    if (scanf("%d %d", &h, &w) != 2) return 0;

    long long **a = (long long **)malloc(h * sizeof(long long *));
    for (int i = 0; i < h; i++) {
        a[i] = (long long *)malloc(w * sizeof(long long));
        for (int j = 0; j < w; j++) scanf("%lld", &a[i][j]);
    }

    /* prefix sums:
       ps[i+1][j+1] = sum of rectangle [0..i][0..j]
    */
    long long **ps = (long long **)malloc((h + 1) * sizeof(long long *));
    for (int i = 0; i <= h; i++) {
        ps[i] = (long long *)calloc(w + 1, sizeof(long long));
    }

    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            ps[i + 1][j + 1] = ps[i][j + 1] + ps[i + 1][j] - ps[i][j] + a[i][j];
        }
    }

    long long total = ps[h][w];

    /* dp[i][j] = best possible value of
       (sum of NE territory) - (sum of SW territory)
       from lattice point (i,j) to (h-1,w-1),
       assuming boundary starts at (i,j) and ends at SE corner.

       Transition:
       Moving east adds cell (i,j) to SW side.
       Moving south adds cell (i,j) to NE side.
       This leads to a simpler equivalent recurrence using suffix/prefix sums,
       but we can derive directly with:
         dp[h-1][w-1] = 0
         last row: only east, cells go to SW
         last col: only south, cells go to NE
         internal: choose max/min by turns.

       However the problem statement only asks the final territory difference
       after players alternately choose moves to maximize the absolute score difference.
       This is equivalent to optimal play on the score difference:
       first player maximizes, second minimizes.
    */

    long long **dp = (long long **)malloc(h * sizeof(long long *));
    for (int i = 0; i < h; i++) dp[i] = (long long *)malloc(w * sizeof(long long));

    dp[h - 1][w - 1] = 0;

    for (int j = w - 2; j >= 0; j--) {
        dp[h - 1][j] = dp[h - 1][j + 1] - a[h - 1][j];
    }
    for (int i = h - 2; i >= 0; i--) {
        dp[i][w - 1] = dp[i + 1][w - 1] + a[i][w - 1];
    }

    for (int i = h - 2; i >= 0; i--) {
        for (int j = w - 2; j >= 0; j--) {
            int turn = (i + j) & 1; /* 0: first player's turn, 1: second player's turn */

            long long moveSouth = dp[i + 1][j] + a[i][j]; /* cell goes to NE */
            long long moveEast  = dp[i][j + 1] - a[i][j]; /* cell goes to SW */

            if (turn == 0) {
                /* first player maximizes final (NE - SW) */
                dp[i][j] = (moveSouth > moveEast) ? moveSouth : moveEast;
            } else {
                /* second player minimizes final (NE - SW) */
                dp[i][j] = (moveSouth < moveEast) ? moveSouth : moveEast;
            }
        }
    }

    long long ans = dp[0][0];
    if (ans < 0) ans = -ans;
    printf("%lld\n", ans);

    for (int i = 0; i < h; i++) {
        free(a[i]);
        free(dp[i]);
    }
    for (int i = 0; i <= h; i++) free(ps[i]);
    free(a);
    free(dp);
    free(ps);

    return 0;
}

