    vector<vector<int>> grid(H, vector<int>(W));
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            cin >> grid[i][j];
        }
    }

    // We'll use DP to compute the difference: 
    // dp[i][j] = best possible (score_north - score_south) from (i,j) to (H-1,W-1)
    // But note that the boundary path divides the island:
    // Cells strictly NE of the path go to player 1 (northeast)
    // Cells strictly SW of the path go to player 2 (southwest)
    // The path itself goes from (0,0) to (H-1,W-1) moving S or E.

    // Let's compute prefix sums for fast territory sum calculation.
    // We can define path cells as the diagonal-like boundary.
    // Actually, for any monotonic path, the NE set = cells above/left of the path? 
    // Let's think: The path goes from NW to SE. 
    // Territory NE: cells that are to the north-east of the path.
    // Territory SW: cells that are to the south-west of the path.
    // The path itself is not counted.

    // This is a classic "divide grid by monotonic path" DP.
    // We'll compute total sum of all cells first.
    long long totalSum = 0;
    for (int i = 0; i < H; i++)
        for (int j = 0; j < W; j++)
            totalSum += grid[i][j];

    // dp[i][j] = best (sum_NE - sum_SW) achievable from cell (i,j) to (H-1,W-1)
    // The path starts from (0,0) and ends at (H-1,W-1).
    // For each cell on the path, NE territory is all cells strictly above the path
    // (i.e., cells with smaller row and larger column relative to path cells? 
    // Actually easier: we can compute contribution per cell based on which side it falls.)

    // Let's reframe: The path splits the grid. If we know for each cell whether it's NE or SW,
    // the difference is sum_NE - sum_SW.
    // But due to the path being monotonic, the split follows: 
    // For any cell (r,c), it belongs to NE if there exists a path cell above-right of it,
    // otherwise SW.

    // Better known approach: Use DP to compute difference directly by deciding at each step
    // which player gets the cell "to the right" (for east move) or "below" (for south move).

    // Let's define dp[i][j] = max possible (sum_NE - sum_SW) from this (i,j) to end,
    // assuming the path goes through (i,j).
    // When moving east from (i,j) to (i,j+1):
    //   - All cells strictly above row i and to the right of column j (i.e., cells (r,c) with r < i and c > j)
    //     become NE territory? Actually no, they were already decided.
    // Instead, think of the path as adding cells to the territories incrementally.

    // I'll use a known solution: precompute prefix sums and use DP that computes 
    // the difference of sums on the two sides.

    vector<vector<long long>> pref(H + 1, vector<long long>(W + 1, 0));
    for (int i = 1; i <= H; i++) {
        for (int j = 1; j <= W; j++) {
            pref[i][j] = grid[i-1][j-1] + pref[i-1][j] + pref[i][j-1] - pref[i-1][j-1];
        }
    }

    auto rectSum = [&](int r1, int c1, int r2, int c2) -> long long {
        if (r1 > r2 || c1 > c2) return 0;
        return pref[r2+1][c2+1] - pref[r1][c2+1] - pref[r2+1][c1] + pref[r1][c1];
    };

    // dp[i][j] = best difference (NE - SW) if path goes through (i,j) to end
    vector<vector<long long>> dp(H, vector<long long>(W, LLONG_MIN));

    // Base: at (H-1, W-1)
    // The path ends here. What is the territory split?
    // NE = cells above and right of the path: none.
    // SW = cells below and left of the path: none.
    // So difference = 0.
    dp[H-1][W-1] = 0;

    for (int i = H-1; i >= 0; i--) {
        for (int j = W-1; j >= 0; j--) {
            if (i == H-1 && j == W-1) continue;

            long long best = LLONG_MIN;

            // Move east: from (i,j) to (i, j+1)
            if (j+1 < W && dp[i][j+1] != LLONG_MIN) {
                // When moving east, the cells strictly above row i and to the right of column j
                // (i.e., rows 0..i-1, cols j+1..W-1) become NE territory.
                // The cells strictly below row i and to the left of column j+1
                // (i.e., rows i+1..H-1, cols 0..j) become SW territory? 
                // Wait, need to think carefully about territory assignment.
                // The path goes through (i,j) then (i,j+1).
                // NE = cells that are north-east of the path.
                // A cell (r,c) is NE if it lies above and to the right of some path segment.
                // For an east move from (i,j) to (i,j+1), the cells that become NE are those above row i and right of column j.
                // The cells that become SW are those below row i and left of column j+1.
                // But some cells may have been assigned earlier.
                // Actually, the incremental assignment when taking an east step from (i,j):
                // - Cells in rows 0..i-1, column j+1 become NE (since they are above the path and to the right of the vertical line at col j).
                // - Cells in row i, columns 0..j become SW (since they are below and left).
                // However, row i, col j is the path itself (ignored).

                long long addNE = rectSum(0, j+1, i-1, W-1);
                long long addSW = rectSum(i, 0, i, j);
                // But careful: row i, col j is path — already excluded.
                // Also row i, col j+1 is next path cell, not counted.

                long long val = dp[i][j+1] + addNE - addSW;
                best = max(best, val);
            }

            // Move south: from (i,j) to (i+1, j)
            if (i+1 < H && dp[i+1][j] != LLONG_MIN) {
                // When moving south, cells to the right of column j and above row i+1 become NE.
                // Cells to the left of column j and below row i become SW.
                long long addNE = rectSum(0, j+1, i, W-1);
                long long addSW = rectSum(i+1, 0, H-1, j);

                long long val = dp[i+1][j] + addNE - addSW;
                best = max(best, val);
            }

            dp[i][j] = best;
        }
    }

    // The answer is the absolute difference
    cout << abs(dp[0][0]) << "\n";

    return 0;
}

