bool vis[305][305][2];

long long solve(int i, int j, int turn) {
    if (i == N-1 && j == M-1) return 0;
    if (vis[i][j][turn]) return dp[i][j][turn];
    vis[i][j][turn] = true;

    long long best;
    vector<long long> options;

    if (j+1 < M) { // move east
        long long gain = (colpre[j][i-1]) - (colpre[j][N-1] - colpre[j][i]);
        // colpre[j][i-1] = sum rows 0..i-1 in col j (NE)
        // sum rows i+1..N-1 in col j (SW, subtract)
        options.push_back(gain + solve(i, j+1, 1-turn));
    }
    if (i+1 < N) { // move south
        long long gain = (rowpre[i][M-1] - rowpre[i][j]) - (rowpre[i][j-1]);
        options.push_back(gain + solve(i+1, j, 1-turn));
    }

    best = turn == 0 ? *max_element(options.begin(), options.end()) : *min_element(options.begin(), options.end());
    dp[i][j][turn] = best;
    return best;
}

