                long long worstForMax = INF;
                if (i < H) {
                    long long add = rectSum(i, j + 1, i, W);
                    worstForMax = min(worstForMax, add + dpMax[i + 1][j]);
                }
                if (j < W) {
                    worstForMax = min(worstForMax, dpMax[i][j + 1]);
                }
                dpMax[i][j] = worstForMax;

                // For dpMin, second player maximizes NE score.
                long long bestForMin = -INF;
                if (i < H) {
                    long long add = rectSum(i, j + 1, i, W);
                    bestForMin = max(bestForMin, add + dpMin[i + 1][j]);
                }
                if (j < W) {
                    bestForMin = max(bestForMin, dpMin[i][j + 1]);
                }
                dpMin[i][j] = bestForMin;
            }
        }
    }

    long long neMax = dpMax[1][1];
    long long neMin = dpMin[1][1];

    // Difference = |NE - SW| = |NE - (total - NE)| = |2*NE - total|
    long long ans = max(llabs(2 * neMax - total), llabs(2 * neMin - total));
    cout << ans << '\n';

    return 0;
}

