import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int h = fs.nextInt();
        int w = fs.nextInt();

        long[][] a = new long[h + 1][w + 1];
        long total = 0;
        for (int i = 1; i <= h; i++) {
            for (int j = 1; j <= w; j++) {
                a[i][j] = fs.nextLong();
                total += a[i][j];
            }
        }

        // Prefix sums
        long[][] ps = new long[h + 1][w + 1];
        for (int i = 1; i <= h; i++) {
            long rowSum = 0;
            for (int j = 1; j <= w; j++) {
                rowSum += a[i][j];
                ps[i][j] = ps[i - 1][j] + rowSum;
            }
        }

        // dp[i][j] = maximum possible score difference
        // (NE territory sum) - (SW territory sum)
        // from cell (i,j) to (h,w), assuming current boundary starts here.
        //
        // Transition:
        // Move east  -> cell (i,j) belongs to SW
        // Move south -> cell (i,j) belongs to NE
        //
        // At (h,w), that final cell belongs to neither side in the partition by the path,
        // so contribution is 0.
        //
        // More conveniently, using area formulas:
        // Let F(i,j) be best possible NE sum from sub-rectangle [i..h][j..w]
        // relative to path from (i,j) to (h,w).
        // But simpler is direct DP on score difference with local cell contribution.

        long[][] dp = new long[h + 2][w + 2];
        boolean[][] vis = new boolean[h + 2][w + 2];

        for (int i = h; i >= 1; i--) {
            for (int j = w; j >= 1; j--) {
                if (i == h && j == w) {
                    dp[i][j] = 0;
                    vis[i][j] = true;
                    continue;
                }

                long best = Long.MIN_VALUE;

                // Move south: current cell goes to NE territory
                if (i + 1 <= h && vis[i + 1][j]) {
                    best = Math.max(best, dp[i + 1][j] + a[i][j]);
                }

                // Move east: current cell goes to SW territory
                if (j + 1 <= w && vis[i][j + 1]) {
                    best = Math.max(best, dp[i][j + 1] - a[i][j]);
                }

                dp[i][j] = best;
                vis[i][j] = true;
            }
        }

        System.out.println(Math.abs(dp[1][1]));
    }
}
